test("the normal UI remains operable at 400 percent browser zoom", async ({ page }) => {
  await page.goto("/");
  // Browser-zoom environment model: quarter the CSS viewport and raise DPR to
  // four, which exercises the same responsive media queries as 400% zoom.
  const cdp = await page.context().newCDPSession(page);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 320,
    height: 180,
    deviceScaleFactor: 4,
    mobile: false,
  });
  await expect.poll(() => page.evaluate(() => window.innerWidth)).toBeLessThanOrEqual(320);
  await expect.poll(() => page.evaluate(() => window.devicePixelRatio)).toBeGreaterThanOrEqual(4);
  await expect(page.getByRole("main", { name: "S.I.R. simulator and editor" })).toBeVisible();
  await page.getByRole("button", { name: "Simulate", exact: true }).click();
  await page.getByRole("button", { name: "Show contextual actions", exact: true }).click();
  await page.getByRole("button", { name: "Open simulator samples", exact: true }).click();
  await expect(page.getByLabel("Simulator samples", { exact: true })).toBeVisible();
});

test("a valid map selected through the visible import control reports success", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Editor", exact: true }).click();
  await page.getByRole("button", { name: "Expand Document / revision panel", exact: true }).click();
  const picker = page.getByLabel("Import SIR map", { exact: true });
  await expect(picker).toBeVisible();
  await picker.setInputFiles({
    name: "invalid.sir-map",
    mimeType: "text/plain",
    buffer: Buffer.from("not a SIR map"),
  });
  await expect(page.getByRole("alert")).toContainText(/not a supported|Map line/i);
  await picker.setInputFiles({
    name: "visible-success.sir-map",
    mimeType: "text/plain",
    buffer: Buffer.from("SIR-MAP 2\nsize 4 4\n"),
  });
  await expect(page.getByRole("alert")).toContainText("Imported map visible-success.sir-map.");
});

test("the visible replay picker rejects corruption then loads the engine-bound retained package", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Review", exact: true }).click();
  const picker = page.getByLabel("Choose replay package", { exact: true });
  await expect(picker).toBeVisible();
  const corrupt = Buffer.from(retainedReplay);
  corrupt[corrupt.length - 1] ^= 0x01;
  await picker.setInputFiles({ name: "corrupt.sirr", mimeType: "application/octet-stream", buffer: corrupt });
  await expect(page.getByText(/corrupt\.sirr rejected:/)).toBeVisible();
  await picker.setInputFiles({ name: "retained.sirr", mimeType: "application/octet-stream", buffer: retainedReplay });
  await expect(page.getByText(/Loaded retained\.sirr/)).toBeVisible();
});

test("the visible background picker rejects an oversized file then reports attachment", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Editor", exact: true }).click();
  await page.getByRole("button", { name: "Expand Document / revision panel", exact: true }).click();
  const picker = page.getByLabel("Choose local raster map background", { exact: true });
  await expect(picker).toBeVisible();
  await picker.setInputFiles({ name: "too-large.png", mimeType: "image/png", buffer: Buffer.alloc(10_485_761) });
  await expect(page.getByRole("alert")).toContainText(/allowed maximum/i);
  await picker.setInputFiles({
    name: "attached.png",
    mimeType: "image/png",
    buffer: Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScL9bQAAAABJRU5ErkJggg==", "base64"),
  });
  await expect(page.getByRole("alert")).toContainText("Attached background attached.png.");
});

test("a curated sample exposes maintained playback and can reset", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: "Simulate", exact: true }).click();
  await page.getByRole("button", { name: "Show contextual actions", exact: true }).click();
  await page.getByRole("button", { name: "Open simulator samples", exact: true }).click();
  await page.getByRole("button", { name: /^Load simulation sample:/ }).first().click();

  const play = page.getByRole("button", { name: "Play tactical timeline", exact: true });
  await expect(play).toBeEnabled();
  await play.click();
  const pause = page.getByRole("button", { name: "Pause tactical timeline", exact: true });
  await expect(pause).toBeVisible();
  await pause.click();
  const runtimeTick = page.getByText(/Authoritative runtime tick \d+/);
  const beforeTick = Number((await runtimeTick.textContent()).match(/\d+/)[0]);
  await page.getByRole("button", { name: "Advance the map simulation one tick", exact: true }).click();
  await expect(runtimeTick).toHaveText(new RegExp(`^Authoritative runtime tick ${beforeTick + 1}\\b`));
  page.once("dialog", (dialog) => dialog.accept());
  await page.getByRole("button", { name: "Reset simulation to the current authored baseline", exact: true }).filter({ hasText: "Reset simulation" }).click();
  await expect(page.getByText(/Authoritative runtime tick 0/)).toBeVisible();
});

